using System.Drawing.Printing;
using Pharma.Bll;
using Pharma.Models;

namespace Pharma.Ui;

/// <summary>Consultation des ventes par période, export CSV et aperçu avant impression.</summary>
public sealed class UC_Rapports : UserControl
{
    private readonly RapportService _rapports; private readonly Utilisateur _user;
    private readonly DateTimePicker _debut=new(){Format=DateTimePickerFormat.Short}; private readonly DateTimePicker _fin=new(){Format=DateTimePickerFormat.Short};
    private readonly ComboBox _type=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=180};
    private readonly DataGridView _grid=new(); private readonly Label _total=new(){AutoSize=true,Font=new Font("Segoe UI Semibold",14,FontStyle.Bold),ForeColor=UiTheme.Navy,TextAlign=ContentAlignment.MiddleRight};
    private List<(DateTime Date,long Id,string Paiement,string Vendeur,decimal Total)> _rows=[];
    public UC_Rapports(RapportService rapports,Utilisateur utilisateur)
    {
        _user=utilisateur;_rapports=rapports;Dock=DockStyle.Fill;BackColor=Color.FromArgb(244,247,250);
        var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3};root.RowStyles.Add(new RowStyle(SizeType.Absolute,50));root.RowStyles.Add(new RowStyle(SizeType.Absolute,64));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.Controls.Add(new Label{Text="Rapports de ventes",Dock=DockStyle.Fill,Font=new Font("Segoe UI Semibold",19,FontStyle.Bold),ForeColor=UiTheme.Navy,TextAlign=ContentAlignment.MiddleLeft},0,0);
        var filters=new FlowLayoutPanel{Dock=DockStyle.Fill,BackColor=Color.White,Padding=new Padding(12),WrapContents=false};_type.Items.AddRange(["Ventes","Produits les plus vendus","État du stock","Péremptions"]);_type.SelectedIndex=0;_type.SelectedIndexChanged+=(_,_)=>Charger();filters.Controls.Add(_type);filters.Controls.Add(new Label{Text="Du",AutoSize=true,Padding=new Padding(12,8,4,0)});_debut.Value=DateTime.Today;filters.Controls.Add(_debut);filters.Controls.Add(new Label{Text="Au",AutoSize=true,Padding=new Padding(12,8,4,0)});_fin.Value=DateTime.Today;filters.Controls.Add(_fin);var actualiser=UiTheme.Button("Actualiser");actualiser.Width=115;actualiser.Click+=(_,_)=>Charger();filters.Controls.Add(actualiser);var csv=UiTheme.Button("Exporter CSV");csv.Width=130;csv.Click+=(_,_)=>ExporterCsv();filters.Controls.Add(csv);var print=UiTheme.Button("Aperçu / imprimer");print.Width=160;print.Click+=(_,_)=>Apercu();filters.Controls.Add(print);filters.Controls.Add(_total);root.Controls.Add(filters,0,1);
        var card=new Panel{Dock=DockStyle.Fill,BackColor=Color.White,Padding=new Padding(8)};UiTheme.StyleGrid(_grid);_grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;card.Controls.Add(_grid);root.Controls.Add(card,0,2);Controls.Add(root);Charger();
    }
    private void Charger(){try{switch(_type.SelectedIndex){case 1:var top=_rapports.ProduitsLesPlusVendus(_debut.Value.Date,_fin.Value.Date,_user);_grid.DataSource=top.Select(x=>new{Produit=x.Designation,Quantite=x.Quantite,ChiffreAffaires=x.ChiffreAffaires,MargeBrute=x.Marge}).ToList();_total.Text=$"Marge brute indicative : {top.Sum(x=>x.Marge):N0} FCFA";break;case 2:var stock=_rapports.EtatStock(_user);_grid.DataSource=stock.Select(x=>new{Référence=x.Reference,Produit=x.Designation,Physique=x.Physique,Vendable=x.Vendable,Etat=x.Etat}).ToList();_total.Text=$"{stock.Count} produit(s)";break;case 3:var exp=_rapports.Peremptions(90,_user);_grid.DataSource=exp.Select(x=>new{Produit=x.Designation,Lot=x.NumeroLot,Péremption=x.Peremption.ToString("dd/MM/yyyy"),Vendable=x.Vendable}).ToList();_total.Text=$"{exp.Count} lot(s) à surveiller";break;default:_rows=_rapports.Ventes(_debut.Value.Date,_fin.Value.Date,_user).ToList();_grid.DataSource=_rows.Select(x=>new{Date=x.Date.ToString("dd/MM/yyyy HH:mm"),Numero=$"V-{x.Id:000000}",Paiement=x.Paiement,Vendeur=x.Vendeur,Total=x.Total}).ToList();_total.Text=$"Total période : {_rows.Sum(x=>x.Total):N0} FCFA";break;}}catch(Exception ex){MessageBox.Show(ex.Message,"Rapport indisponible",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
    private void ExporterCsv(){using var dlg=new SaveFileDialog{Filter="Fichier CSV (*.csv)|*.csv",FileName=$"rapport-{DateTime.Today:yyyyMMdd}.csv"};if(dlg.ShowDialog(FindForm())!=DialogResult.OK)return;try{var lines=new List<string>();if(_type.SelectedIndex==0){lines.Add("Date;Numero;Paiement;Vendeur;Total");lines.AddRange(_rows.Select(x=>$"{x.Date:yyyy-MM-dd HH:mm};V-{x.Id:000000};{Echapper(x.Paiement)};{Echapper(x.Vendeur)};{x.Total.ToString(System.Globalization.CultureInfo.InvariantCulture)}"));}else{var headers=_grid.Columns.Cast<DataGridViewColumn>().Select(x=>Echapper(x.HeaderText));lines.Add(string.Join(';',headers));foreach(DataGridViewRow row in _grid.Rows){if(row.IsNewRow)continue;lines.Add(string.Join(';',row.Cells.Cast<DataGridViewCell>().Select(x=>Echapper(Convert.ToString(x.Value,System.Globalization.CultureInfo.InvariantCulture)??""))));}}File.WriteAllLines(dlg.FileName,lines,new System.Text.UTF8Encoding(true));MessageBox.Show("Export terminé.","Rapport",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show(ex.Message,"Export impossible",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
    private static string Echapper(string text)=>$"\"{text.Replace("\"","\"\"")}\"";
    private void Apercu(){if(_grid.Rows.Cast<DataGridViewRow>().All(x=>x.IsNewRow)){MessageBox.Show("Aucune donnée à imprimer.");return;}var doc=new PrintDocument();doc.DocumentName="Rapport Pharma";var i=0;doc.PrintPage+=(_,e)=>{var g=e.Graphics!;using var font=new Font("Segoe UI",8);using var bold=new Font("Segoe UI",12,FontStyle.Bold);float y=45;g.DrawString($"Rapport - {_type.Text}",bold,Brushes.Black,45,y);y+=28;g.DrawString($"Période : {_debut.Value:dd/MM/yyyy} — {_fin.Value:dd/MM/yyyy}",font,Brushes.Black,45,y);y+=30;foreach(DataGridViewRow row in _grid.Rows){if(row.IsNewRow)continue;if(y>e.MarginBounds.Bottom-30){e.HasMorePages=true;return;}var text=string.Join("   ",row.Cells.Cast<DataGridViewCell>().Select(x=>Convert.ToString(x.Value,System.Globalization.CultureInfo.InvariantCulture)));g.DrawString(text,font,Brushes.Black,45,y);y+=20;i++;}e.HasMorePages=false;};using var preview=new PrintPreviewDialog{Document=doc,Width=1000,Height=700};preview.ShowDialog(FindForm());}
}
